/// GENERATED from actors.yaml: the strongly-typed client for ONE `Customer` mailbox lane --
/// `actor_id` is the addressed instance and the partition is derived by `declared_lane` from the
/// DECLARED `mailbox.partitions` width. The only door to this actor.
///
/// This client does NOT carry the width (#596). It used to be emitted as a literal into every
/// send/schedule call, which made each generated client an independent copy of a routing constant
/// that only ever has one correct value -- and disagreeing copies of that constant are how one
/// aggregate ends up in two lanes, each with a live lease.
pub struct CustomerClient {
    door: ActorDoor,
    actor_id: uuid::Uuid,
}

impl CustomerClient {
    /// A client addressing the `Customer` instance `actor_id`.
    pub fn new(mailbox: Arc<dyn Mailbox>, actor_id: uuid::Uuid) -> Self {
        Self { door: ActorDoor::new(mailbox), actor_id }
    }

    /// Enqueue one typed COMMAND on this lane (kind COMMAND). Delegates to the door's
    /// `send_command`, which builds the row with the shared `command_entry` constructor -- the
    /// very row `enqueue_worker_command` builds for the same inputs, field for field.
    pub async fn send<M: CustomerCommand>(
        &self,
        msg: M,
        env: Envelope,
    ) -> Result<EnqueueOutcome, DomainError> {
        let payload = serde_json::to_value(&msg)
            .map_err(|e| DomainError::Repository(format!("{} payload: {e}", M::MESSAGE_TYPE)))?;
        self.door.assert_addressed("CustomerClient", self.actor_id, M::MESSAGE_TYPE, &payload)?;
        self.door
            .send_command("Customer", self.actor_id, M::MESSAGE_TYPE, payload, env)
            .await
    }
}
